{
    $spreadsheet = new Spreadsheet();
    $sheet = $spreadsheet->getActiveSheet();
    $sheet->fromArray([
        ['a1', 'b1', 'c1'],
        ['a2', 'b2', null],
    ]);

    $cells = $sheet->toArray();
    self::assertSame('a1', $cells[0][0]);
    self::assertSame('b1', $cells[0][1]);
    self::assertSame('c1', $cells[0][2]);
    self::assertSame('a2', $cells[1][0]);
    self::assertSame('b2', $cells[1][1]);
